class Rectangle { setW(w){this.w=w} setH(h){this.h=h} }
class Square extends Rectangle {
  setW(w){ this.w=this.h=w }   // 정사각형이라 H 도 바꿈
  setH(h){ this.w=this.h=h }
}
// "직사각형은 W·H 를 독립으로 바꿀 수 있다"는 계약을
// Square 가 깬다 → Rectangle 자리에 Square 를 넣으면 코드가 깨짐
//   → "수학적 is-a" ≠ "코드상 치환 가능"

class Player {
  constructor(private mover: Mover, private attacker: Attacker) {}
  move() { this.mover.move(); }       // 능력에 위임
  attack() { this.attacker.attack(); }
}
// 이동·공격을 독립적으로 조합·교체
new Player(new WalkMover(), new SwordAttacker());  // 전사
new Player(new FlyMover(),  new FireAttacker());   // 드래곤
// 새 능력 추가 = 새 클래스 하나 (기존 코드 안 건드림)
